import { db } from "@/lib/db";

export async function POST(request: Request) {
  try {
    const body = await request.json();
    const { title, airtimeMin } = body;

    if (!title || !airtimeMin) {
      return new Response("Title and airtimeMin are required", { status: 400 });
    }

    if (airtimeMin < 1 || airtimeMin > 360) {
      return new Response("AirtimeMin must be a finite integer between 1 and 360", { status: 400 });
    }

    const existingBroadcast = await db.broadcast.findUnique({
      where: { title },
    });

    if (existingBroadcast) {
      return new Response("Broadcast with the same title already exists", { status: 409 });
    }

    const newBroadcast = await db.broadcast.create({
      data: {
        title,
        airtimeMin,
      },
    });

    return new Response(JSON.stringify(newBroadcast), { status: 201 });
  } catch (error) {
    console.error("Error creating broadcast:", error);
    return new Response("Internal Server Error", { status: 500 });
  }
}

